+class _SHAInlineBuilder(Builder):
+    def __init__(self,node,names,signatures,total,helpers,hot_calls):
+        super().__init__(node,names,signatures,total)
+        self.helpers=helpers
+        self.hot_calls=hot_calls
+
+    def expr(self,node):
+        if (self.node.name!='sha_file' or not isinstance(node,ast.Call)
+                or not isinstance(node.func,ast.Name) or node.func.id not in self.helpers
+                or (node.func.id=='sha_put' and id(node) not in self.hot_calls)):
+            return super().expr(node)
+        name=node.func.id
+        helper=self.helpers[name]
+        assert not node.keywords and len(node.args)==len(helper.args.args)
+        # Identical evaluation/cast order to Builder.expr's original call path.
+        actuals=[self.expr(arg) for arg in node.args]
+        types,returned_type=self.signatures[name]
+        converted=[self.cast(value,typ) if value[1]!=typ else value
+                   for value,typ in zip(actuals,types)]
+        outside=self.env
+        self.env={formal.arg:value for formal,value in zip(helper.args.args,converted)}
+        try:
+            for statement in helper.body[:-1]:
+                if isinstance(statement,ast.Assign):
+                    assert len(statement.targets)==1 and isinstance(statement.targets[0],ast.Name)
+                    self.env[statement.targets[0].id]=self.expr(statement.value)
+                else:
+                    assert isinstance(statement,ast.Expr)
+                    self.expr(statement.value)
+            ending=helper.body[-1]
+            assert isinstance(ending,ast.Return)
+            result=self.cast(self.expr(ending.value),returned_type)
+        finally:
+            self.env=outside
+        return result
+
+
+def _sha_inline_plan(nodes):
+    """Only fixed straight-line helpers and only hot SHA word stores inline.
+
+    Keep the 72 one-time initialization calls out of the caller so its SSA
+    indices remain within the original 2,048-name compiler profile. Function
+    order, helpers, byte operations, nonce and state checks remain unchanged.
+    """
+    by_name = {node.name: node for node in nodes}
+    helpers = {name: by_name[name] for name in ('sha_rotate', 'sha_get', 'sha_put')}
+    for name, node in helpers.items():
+        assert node.returns.id == 'u64' and isinstance(node.body[-1], ast.Return), name
+        assert all(isinstance(statement, (ast.Assign, ast.Expr)) for statement in node.body[:-1]), name
+        for item in ast.walk(node):
+            assert not isinstance(item, (ast.If, ast.While, ast.For, ast.Try, ast.With, ast.Raise)), name
+            if isinstance(item, ast.Call):
+                assert isinstance(item.func, ast.Name) and item.func.id in ('byte', 'store'), name
+    hot_calls = {id(item) for loop in ast.walk(by_name['sha_file']) if isinstance(loop, ast.While)
+                 for item in ast.walk(loop) if isinstance(item, ast.Call)}
+    return helpers, hot_calls
+
+
